SET LOCAL aidash.scope = 'deployment';
LOCK TABLE authorization_catalog IN SHARE ROW EXCLUSIVE MODE;
WITH widened AS (
INSERT INTO "authorization_catalog" ("tenant", "node", "entry_id", "entry_version", "enabled", "carry_over", "scope", "restriction", "carried_from_version", "carried_from_approver", "revision") SELECT "choice"."tenant", "nodes"."name", "choice"."entry_id", "choice"."entry_version", "choice"."enabled", "choice"."carry_over", 'deployment', CASE WHEN jsonb_typeof("choice"."restriction"->'subjects') = 'array' THEN jsonb_set("choice"."restriction", '{subjects}', COALESCE((SELECT jsonb_agg(CASE WHEN s LIKE 'aidash://%/' || "choice"."node" || '/agents/%' THEN replace(s, '/' || "choice"."node" || '/agents/', '/' || "nodes"."name" || '/agents/') ELSE s END ORDER BY s) FROM jsonb_array_elements_text("choice"."restriction"->'subjects') AS subjects(s)), '[]'::jsonb)) ELSE "choice"."restriction" END, "choice"."carried_from_version", "choice"."carried_from_approver", COALESCE("previous"."revision", 0) + 1 FROM (SELECT DISTINCT ON ("authorization_catalog"."tenant", "authorization_catalog"."entry_id", "authorization_catalog"."entry_version") "authorization_catalog"."tenant", "authorization_catalog"."node", "authorization_catalog"."entry_id", "authorization_catalog"."entry_version", "authorization_catalog"."enabled", "authorization_catalog"."carry_over", "authorization_catalog"."scope", "authorization_catalog"."restriction", "authorization_catalog"."carried_from_version", "authorization_catalog"."carried_from_approver", "authorization_catalog"."revision" FROM "authorization_catalog" INNER JOIN "registry" ON "registry"."tenant" = "authorization_catalog"."tenant" AND "registry"."id" = "authorization_catalog"."entry_id" AND "registry"."version" = "authorization_catalog"."entry_version" WHERE "registry"."kind" = 'model' AND NOT EXISTS (SELECT 1 FROM "node_deletions" WHERE "node_deletions"."tenant" = "authorization_catalog"."tenant" AND "node_deletions"."node" = "authorization_catalog"."node" AND "restored_at" IS NULL) ORDER BY "authorization_catalog"."tenant" ASC, "authorization_catalog"."entry_id" ASC, "authorization_catalog"."entry_version" ASC, "authorization_catalog"."enabled" DESC, "authorization_catalog"."node" ASC) AS "choice" INNER JOIN "nodes" ON "nodes"."tenant" = "choice"."tenant" LEFT JOIN "authorization_catalog" AS "previous" ON "previous"."tenant" = "choice"."tenant" AND "previous"."node" = "nodes"."name" AND "previous"."entry_id" = "choice"."entry_id" AND "previous"."entry_version" = "choice"."entry_version" WHERE NOT EXISTS (SELECT 1 FROM "node_deletions" WHERE "node_deletions"."tenant" = "nodes"."tenant" AND "node_deletions"."node" = "nodes"."name" AND "restored_at" IS NULL) ON CONFLICT ("tenant", "node", "entry_id", "entry_version") DO UPDATE SET "enabled" = EXCLUDED."enabled", "carry_over" = EXCLUDED."carry_over", "scope" = EXCLUDED."scope", "restriction" = EXCLUDED."restriction", "carried_from_version" = EXCLUDED."carried_from_version", "carried_from_approver" = EXCLUDED."carried_from_approver", "revision" = EXCLUDED."revision" RETURNING "tenant", "node", "entry_id", "entry_version", "enabled", "carry_over", "scope", "restriction", "carried_from_version", "carried_from_approver", "revision"
)
INSERT INTO "authorization_catalog_history" ("tenant", "node", "entry_id", "entry_version", "enabled", "carry_over", "scope", "restriction", "carried_from_version", "carried_from_approver", "revision", "actor") SELECT "tenant", "node", "entry_id", "entry_version", "enabled", "carry_over", "scope", "restriction", "carried_from_version", "carried_from_approver", "revision", 'migration:identity/0116_model_approval_scope' FROM "widened";
